type BrowserRunLifecycleEvent =
  'load' | 'domcontentloaded' | 'networkidle0' | 'networkidle2';

type BrowserRunResourceType =
  | 'document'
  | 'stylesheet'
  | 'image'
  | 'media'
  | 'font'
  | 'script'
  | 'texttrack'
  | 'xhr'
  | 'fetch'
  | 'prefetch'
  | 'eventsource'
  | 'websocket'
  | 'manifest'
  | 'signedexchange'
  | 'ping'
  | 'cspviolationreport'
  | 'preflight'
  | 'other';

/** Options fields shared by all quick actions. */
interface BrowserRunBaseOptions {
  /** Adds \`<script>\` tags into the page with the desired URL or content.
   * @see https://pptr.dev/api/puppeteer.frameaddscripttagoptions
   */
  addScriptTag?: Array<{
    content?: string;
    url?: string;
    type?: string;
    id?: string;
  }>;
  /** Adds \`<link rel="stylesheet">\` or \`<style>\` tags into the page.
   * @see https://pptr.dev/api/puppeteer.frameaddstyletagoptions
   */
  addStyleTag?: Array<{ content?: string; url?: string }>;
  /** Provide credentials for HTTP authentication. @see https://pptr.dev/api/puppeteer.credentials */
  authenticate?: { username: string; password: string };
  /** Set cookies before navigating. @see https://pptr.dev/api/puppeteer.cookieparam */
  cookies?: Array<{
    name: string;
    value: string;
    url?: string;
    domain?: string;
    path?: string;
    secure?: boolean;
    httpOnly?: boolean;
    sameSite?: 'Strict' | 'Lax' | 'None';
    expires?: number;
    priority?: 'Low' | 'Medium' | 'High';
    sameParty?: boolean;
    sourceScheme?: 'Unset' | 'NonSecure' | 'Secure';
    sourcePort?: number;
    partitionKey?: string;
  }>;
  /** Emulate a specific CSS media type (e.g. \`"screen"\`, \`"print"\`). */
  emulateMediaType?: string;
  /** Navigation options. @see https://pptr.dev/api/puppeteer.gotooptions */
  gotoOptions?: {
    /** Navigation timeout in milliseconds (max 60 000). @default 30000 */
    timeout?: number;
    /** When to consider navigation complete. @default "domcontentloaded" */
    waitUntil?: BrowserRunLifecycleEvent | BrowserRunLifecycleEvent[];
    referer?: string;
    referrerPolicy?: string;
  };
  /** Block requests matching these regex patterns. Mutually exclusive with \`allowRequestPattern\`. */
  rejectRequestPattern?: string[];
  /** Only allow requests matching these regex patterns. Mutually exclusive with \`rejectRequestPattern\`. */
  allowRequestPattern?: string[];
  /** Block requests of these resource types. Mutually exclusive with \`allowResourceTypes\`. */
  rejectResourceTypes?: BrowserRunResourceType[];
  /** Only allow requests of these resource types. Mutually exclusive with \`rejectResourceTypes\`. */
  allowResourceTypes?: BrowserRunResourceType[];
  /** Additional HTTP headers sent with every request. */
  setExtraHTTPHeaders?: Record<string, string>;
  /** Whether JavaScript is enabled on the page. */
  setJavaScriptEnabled?: boolean;
  /** Override the default user agent string.
   * @default "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/119.0.0.0 Safari/537.36"
   * */
  userAgent?: string;
  /** Set the browser viewport size.
   * @see https://pptr.dev/api/puppeteer.viewport
   * @default {width:1920,height:1080}
   * */
  viewport?: {
    width: number;
    height: number;
    deviceScaleFactor?: number;
    isMobile?: boolean;
    isLandscape?: boolean;
    hasTouch?: boolean;
  };
  /** Wait for a CSS selector to appear in the page before proceeding.
   * @see https://pptr.dev/api/puppeteer.waitforselectoroptions
   */
  waitForSelector?: {
    selector: string;
    hidden?: true;
    visible?: true;
    /** Timeout in milliseconds. Max 120000 */
    timeout?: number;
  };
  /** Wait for a fixed delay in milliseconds before proceeding. Max 120000 */
  waitForTimeout?: number;
  /** When true, continue on best-effort when awaited events fail or timeout. */
  bestAttempt?: boolean;
  /** Maximum duration in milliseconds for the browser action after page load. Max 120000 */
  actionTimeout?: number;
  /** Cache time to live in seconds (0-86400). Set to 0 to disable.
   * @default 5
   */
  cacheTTL?: number;
}

/** Backend selection for quick actions. */
interface BrowserRunAlternateBackendOptions {
  /** Render with an alternate browser backend instead of the default one. */
  browser?: 'kitesurf';
}

/** Common options shared by all quick actions. Exactly one of \`url\` or \`html\` must be provided.*/
type BrowserRunCommonOptions = BrowserRunBaseOptions &
  BrowserRunAlternateBackendOptions &
  (
    | {
        /** URL to navigate to, e.g. \`"https://example.com"\`. */
        url: string;
      }
    | {
        /** Set the HTML content of the page directly. */
        html: string;
      }
  );

type BrowserRunPuppeteerScreenshotOptions = {
  /** @default "png" */
  type?: 'png' | 'jpeg' | 'webp';
  /** @default "binary" */
  encoding?: 'binary' | 'base64';
  quality?: number;
  fullPage?: boolean;
  clip?: {
    x: number;
    y: number;
    width: number;
    height: number;
    scale?: number;
  };
  omitBackground?: boolean;
  optimizeForSpeed?: boolean;
  captureBeyondViewport?: boolean;
  fromSurface?: boolean;
};

type BrowserRunScreenshotOptions = BrowserRunCommonOptions & {
  /** CSS selector of the element to screenshot. */
  selector?: string;
  /** When true, scroll the entire page before taking the screenshot. */
  scrollPage?: boolean;
  /** @see https://pptr.dev/api/puppeteer.screenshotoptions */
  screenshotOptions?: BrowserRunPuppeteerScreenshotOptions;
};

type BrowserRunPDFOptions = BrowserRunCommonOptions & {
  /** @see https://pptr.dev/api/puppeteer.pdfoptions */
  pdfOptions?: {
    /** @default 1 */
    scale?: number;
    /** @default false */
    displayHeaderFooter?: boolean;
    headerTemplate?: string;
    footerTemplate?: string;
    /** @default false */
    printBackground?: boolean;
    /** @default false */
    landscape?: boolean;
    pageRanges?: string;
    /** @default "letter" */
    format?:
      | 'letter'
      | 'legal'
      | 'tabloid'
      | 'ledger'
      | 'a0'
      | 'a1'
      | 'a2'
      | 'a3'
      | 'a4'
      | 'a5'
      | 'a6';
    width?: string | number;
    height?: string | number;
    /** @default false */
    preferCSSPageSize?: boolean;
    margin?: {
      top?: string | number;
      right?: string | number;
      bottom?: string | number;
      left?: string | number;
    };
    /** @default false */
    omitBackground?: boolean;
    /** @default true */
    tagged?: boolean;
    /** @default false */
    outline?: boolean;
    /** @default 30000 */
    timeout?: number;
  };
};

type BrowserRunScrapeOptions = BrowserRunCommonOptions & {
  /** CSS selectors to scrape. At least one element is required. */
  elements: Array<{ selector: string }>;
};

type BrowserRunLinksOptions = BrowserRunCommonOptions & {
  /** When true, only return links that are visible on the page. @default false */
  visibleLinksOnly?: boolean;
  /** When true, exclude links pointing to external domains. @default false */
  excludeExternalLinks?: boolean;
};

type BrowserRunSnapshotFormat =
  'content' | 'screenshot' | 'markdown' | 'accessibilityTree';

type BrowserRunSnapshotOptions = BrowserRunCommonOptions & {
  /** Which representations of the page to return. At least two distinct formats
   * are required; request a single format from its dedicated action instead.
   * @default ["content","screenshot"]
   */
  formats?: BrowserRunSnapshotFormat[];
  /** @see https://pptr.dev/api/puppeteer.screenshotoptions */
  screenshotOptions?: Omit<BrowserRunPuppeteerScreenshotOptions, 'encoding'>;
};

/** Options for the \`accessibilityTree\` quick action. */
type BrowserRunAccessibilityTreeOptions = BrowserRunCommonOptions & {
  /** When true, prune nodes that carry no semantic meaning, such as generic
   * containers. Defaults to true, or to false when \`root\` is set so that the
   * requested subtree is returned as-is.
   */
  interestingOnly?: boolean;
  /** CSS selector limiting the tree to the matching element's subtree.
   * A selector that matches nothing yields \`accessibilityTree: null\` with
   * HTTP 200; a malformed selector is an error.
   */
  root?: string;
};

interface BrowserRunJsonBaseOptions {
  /** Custom AI models to try in order. Max 3. Falls back to next on error. */
  custom_ai?: Array<{
    /** Model ID in \`<provider>/<model_name>\` format, e.g. \`"workers-ai/@cf/meta/llama-3.3-70b-instruct-fp8-fast"\`. */
    model: string;
    /** Bearer token. Not needed for workers-ai models. */
    authorization?: string;
  }>;
}

/**
 * Options for the \`json\` quick action.
 * At least one of \`prompt\` or \`response_format\` must be provided.
 */
type BrowserRunJsonOptions = BrowserRunCommonOptions &
  BrowserRunJsonBaseOptions &
  (
    | {
        /** Natural-language prompt describing what data to extract. */
        prompt: string;
        /** Structured output schema for the AI model. @see https://developers.cloudflare.com/workers-ai/json-mode/ */
        response_format?: AiTextGenerationResponseFormat;
      }
    | {
        /** Natural-language prompt describing what data to extract. */
        prompt?: string;
        /** Structured output schema for the AI model. @see https://developers.cloudflare.com/workers-ai/json-mode/ */
        response_format: AiTextGenerationResponseFormat;
      }
  );

type BrowserRunContentOptions = BrowserRunCommonOptions;
type BrowserRunMarkdownOptions = BrowserRunCommonOptions;

type BrowserRunRedirectHop = {
  /** URL that returned the redirect. */
  url: string;
  /** HTTP status of the redirect. */
  status: number;
  /** Redirect response headers, including \`location\`. */
  headers: Record<string, string>;
};

type BrowserRunResponseMeta = {
  /** HTTP status code of the rendered page */
  status: number;
  /** Page title */
  title: string;
  /** Origin response headers, lowercased. Repeated headers are joined with a newline. Credential and transport-only headers that do not survive rendering are omitted. */
  headers?: Record<string, string>;
  /** URL that served the response, after any redirects the browser followed. */
  finalUrl?: string;
  /** HTTP redirects followed to reach \`finalUrl\`, oldest first. Omitted for direct navigation and for client-side redirects such as meta refresh. An empty array means redirects occurred but their intermediate responses could not be read. */
  redirectChain?: BrowserRunRedirectHop[];
};

/**
 * A node in the page's accessibility tree, as exposed to assistive technology.
 * \`role\` is the only field always present; the rest are populated when the
 * underlying element defines them.
 * @see https://pptr.dev/api/puppeteer.serializedaxnode
 */
interface BrowserRunSerializedAXNode {
  /** The ARIA role, e.g. \`"button"\`, \`"heading"\`, \`"RootWebArea"\`. */
  role: string;
  /** The \`aria-autocomplete\` value. */
  autocomplete?: string;
  /** Checked state of a checkbox, radio, or menu item. */
  checked?: boolean | 'mixed';
  /** Accessible description, typically from \`aria-describedby\` or \`title\`. */
  description?: string;
  disabled?: boolean;
  expanded?: boolean;
  /** Whether the element currently holds keyboard focus. */
  focused?: boolean;
  /** The kind of popup the element triggers, e.g. \`"menu"\`, \`"dialog"\`. */
  haspopup?: string;
  /** The \`aria-invalid\` value. */
  invalid?: string;
  /** Keyboard shortcuts bound to the element, from \`aria-keyshortcuts\`. */
  keyshortcuts?: string;
  /** Hierarchical level, e.g. the heading level of an \`<h2>\`. */
  level?: number;
  /** Whether the element is a modal dialog. */
  modal?: boolean;
  /** Whether a text input accepts multiple lines. */
  multiline?: boolean;
  /** Whether more than one option can be selected. */
  multiselectable?: boolean;
  /** Accessible name, e.g. a button's label or an image's alt text. */
  name?: string;
  orientation?: string;
  /** Pressed state of a toggle button. */
  pressed?: boolean | 'mixed';
  readonly?: boolean;
  required?: boolean;
  /** Author-supplied role description, from \`aria-roledescription\`. */
  roledescription?: string;
  selected?: boolean;
  /** Current value of an input or range element. */
  value?: string | number;
  valuemax?: number;
  valuemin?: number;
  /** Human-readable form of \`value\`, from \`aria-valuetext\`. */
  valuetext?: string;
  /** Child nodes. Absent for leaf nodes. */
  children?: BrowserRunSerializedAXNode[];
}

/** Success response for \`content\` action. */
type BrowserRunContentSuccessResponse = {
  success: true;
  /** Extracted HTML content */
  result: string;
  meta: BrowserRunResponseMeta;
};

/** Success response for \`links\` action. */
type BrowserRunLinksSuccessResponse = {
  success: true;
  /** Extracted links */
  result: string[];
  meta: BrowserRunResponseMeta;
};

/** Success response for \`scrape\` action. */
type BrowserRunScrapeSuccessResponse = {
  success: true;
  result: Array<{
    /** The CSS selector used to find elements. */
    selector: string;
    /** Array of elements matching the selector. */
    results: Array<{
      /** Outer HTML of the element. */
      html: string;
      /** Text content of the element. */
      text: string;
      /** Width of the element in pixels. */
      width: number;
      /** Height of the element in pixels. */
      height: number;
      /** Top position of the element relative to the viewport in pixels. */
      top: number;
      /** Left position of the element relative to the viewport in pixels. */
      left: number;
      /** Array of HTML attributes on the element. */
      attributes: Array<{
        /** Attribute name. */
        name: string;
        /** Attribute value. */
        value: string;
      }>;
    }>;
  }>;
  meta: BrowserRunResponseMeta;
};

/** Success response for \`snapshot\` action. Each field is present only when the
 * corresponding entry was requested in \`formats\`.
 */
type BrowserRunSnapshotSuccessResponse = {
  success: true;
  result: {
    /** HTML content of the page. */
    content?: string;
    /** Base64-encoded screenshot image. */
    screenshot?: string;
    /** Markdown content. Prefixed with YAML frontmatter (e.g. \`title\`) when the
     * page provides that metadata.
     */
    markdown?: string;
    /** Root of the page's accessibility tree. */
    accessibilityTree?: BrowserRunSerializedAXNode;
  };
  meta: BrowserRunResponseMeta;
};

/** Success response for \`accessibilityTree\` action. */
type BrowserRunAccessibilityTreeSuccessResponse = {
  success: true;
  result: {
    /** Root of the accessibility tree, or \`null\` when \`root\` matched no element. */
    accessibilityTree: BrowserRunSerializedAXNode | null;
  };
  meta: BrowserRunResponseMeta;
};

/** Success response for \`json\` action. */
type BrowserRunJsonSuccessResponse = {
  success: true;
  /** JSON data extracted from the page using an AI model */
  result: Record<string, unknown>;
  meta: BrowserRunResponseMeta;
};

/** Success response for \`markdown\` action. */
type BrowserRunMarkdownSuccessResponse = {
  success: true;
  /** Extracted markdown content */
  result: string;
  meta: BrowserRunResponseMeta;
};

/** Error response for BrowserRun actions. */
type BrowserRunErrorResponse = {
  success: false;
  errors: { message: string; code?: number; detail?: string; path?: string }[];
};

/** Error response for BrowserRun \`json\` action. */
type BrowserRunJsonErrorResponse = BrowserRunErrorResponse & {
  /** Raw AI response text for debugging */
  rawAiResponse?: string;
};

/** Session-scoped guardrails applied when acquiring a browser session. */
type BrowserRunAcquireGuardrails = {
  /** Domains that the browser may access. An empty list denies all domains. */
  allowedDomains?: string[];
  /** Named domain sets that the browser may access. */
  allowedDomainSets?: string[];
};

/** Options for acquiring a new browser session. */
type BrowserRunAcquireOptions = {
  /** Idle session lifetime in milliseconds. */
  keepAlive?: number;
  /** Record the browser session. */
  recording?: boolean;
  /** Geoegress hint as an ISO-3166 alpha-2 country code. */
  location?: string;
  /** Map hostnames to caller-provided Workers that handle outbound requests. */
  outboundByHost?: Record<string, Fetcher>;
  /** Session-scoped network guardrails. */
  guardrails?: BrowserRunAcquireGuardrails;
  /** Include the session's DevTools targets in the result. */
  targets?: boolean;
  /** Lifetime of target live-view URLs in milliseconds. */
  liveViewUrlExpiresInMs?: number;
};

/** Metadata returned when a browser session is acquired. */
type BrowserRunAcquireResult = {
  sessionId: string;
  targets?: BrowserRunDevToolsTarget[];
};

/** Options for connecting to an already-acquired browser session. */
type BrowserRunConnectOptions = {
  /** Connect to a specific page target instead of the browser-level CDP endpoint. */
  targetId?: string;
};

/** Connection capability returned by \`connectSession()\` and \`launch()\`. */
type BrowserRunConnection = {
  sessionId: string;
  /** A session-pinned Fetcher. Use its \`fetch()\` method for a WebSocket upgrade. */
  webSocket: Fetcher;
  targets?: BrowserRunDevToolsTarget[];
};

/** The UI mode for a live-view link. */
type BrowserRunLiveViewMode = 'devtools' | 'tab' | 'full';

/** Connection-scoped guardrails applied to a live-view link. */
type BrowserRunConnectionGuardrails = {
  mode: 'readonly';
};

/** Options for minting a live-view link. */
type BrowserRunLiveViewOptions = {
  mode?: BrowserRunLiveViewMode;
  targetId?: string;
  expiresInMs?: number;
  guardrails?: BrowserRunConnectionGuardrails;
};

/** Live-view link metadata. */
type BrowserRunLiveView = {
  webSocketDebuggerUrl: string;
  devtoolsFrontendUrl: string;
  id: string;
  options: {
    mode: BrowserRunLiveViewMode;
    guardrails?: BrowserRunConnectionGuardrails;
  };
};

/** Options for listing active browser sessions. */
type BrowserRunListSessionsOptions = {
  limit?: number;
  offset?: number;
};

/** Options for listing session history. */
type BrowserRunHistoryOptions = {
  limit?: number;
  offset?: number;
};

/** A browser session returned by the session-management methods. */
type BrowserRunSession = {
  sessionId: string;
  startTime?: number;
  endTime?: number;
  closeReason?: number;
  closeReasonText?: string;
  connectionId?: string;
  connectionStartTime?: number;
  connectionEndTime?: number;
  lastUpdated?: number;
  webSocketDebuggerUrl?: string;
  devtoolsFrontendUrl?: string;
};

/** Account browser-session and browser-time limits. */
type BrowserRunLimits = {
  activeSessions: Array<{ id: string }>;
  maxConcurrentSessions: number;
  allowedBrowserAcquisitions: number;
  timeUntilNextAllowedBrowserAcquisition: number;
  usedBrowserTimeSeconds?: number;
};

/** A browser target returned by the DevTools JSON methods. */
type BrowserRunDevToolsTarget = {
  id: string;
  type: string;
  url: string;
  title?: string;
  description?: string;
  webSocketDebuggerUrl?: string;
  devtoolsFrontendUrl?: string;
};

/** Browser and protocol version metadata. */
type BrowserRunDevToolsVersion = {
  Browser: string;
  'Protocol-Version': string;
  'User-Agent': string;
  'V8-Version': string;
  'WebKit-Version': string;
  webSocketDebuggerUrl: string;
};

/** A DevTools protocol domain. Protocol definitions may gain additional fields over time. */
interface BrowserRunDevToolsProtocolDomain extends Record<string, unknown> {
  domain: string;
  experimental?: boolean;
  dependencies?: string[];
  types?: Array<Record<string, any>>;
  commands?: Array<Record<string, any>>;
  events?: Array<Record<string, any>>;
}

/** The DevTools protocol definition. Additional protocol fields may be returned by Chrome. */
interface BrowserRunDevToolsProtocol extends Record<string, any> {
  domains: BrowserRunDevToolsProtocolDomain[];
  version?: { major: string; minor: string };
}

/** Options shared by DevTools target-listing and target-creation methods. */
type BrowserRunTargetOptions = {
  liveViewUrlExpiresInMs?: number;
};

/** Result returned by DevTools target activation and close methods. */
type BrowserRunTargetActionResult = {
  message: string;
};

/** Methods exposed by the nested \`devtools\` binding target. */
type BrowserRunDevtools = {
  getVersion(sessionId: string): Promise<BrowserRunDevToolsVersion>;
  getProtocol(sessionId: string): Promise<BrowserRunDevToolsProtocol>;
  listTargets(
    sessionId: string,
    options?: BrowserRunTargetOptions
  ): Promise<BrowserRunDevToolsTarget[]>;
  getTarget(
    sessionId: string,
    targetId: string
  ): Promise<BrowserRunDevToolsTarget>;
  newTarget(
    sessionId: string,
    url?: string,
    options?: BrowserRunTargetOptions
  ): Promise<BrowserRunDevToolsTarget>;
  activateTarget(
    sessionId: string,
    targetId: string
  ): Promise<BrowserRunTargetActionResult>;
  closeTarget(
    sessionId: string,
    targetId: string
  ): Promise<BrowserRunTargetActionResult>;
};

/** Result returned when closing a browser session. */
type BrowserRunCloseSessionResult = {
  status: 'closing' | 'closed';
};

/**
 * Browser Run API binding for automating headless browsers.
 * @see https://developers.cloudflare.com/browser-run/
 */
declare abstract class BrowserRun {
  /**
   * Send a raw HTTP request to the Browser Run API.
   * Used by libraries like \`@cloudflare/puppeteer\` to acquire and connect to a browser instance.
   * @see https://developers.cloudflare.com/browser-run/
   */
  fetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response>;

  /**
   * Take a screenshot of a web page.
   * @param action - Must be \`'screenshot'\`.
   * @param options - Screenshot options including viewport, selectors, and image format.
   * @returns A \`Response\` containing one of:
   *
   * **Success (HTTP 200):**
   * - Binary image data with \`Content-Type: image/png\`, \`image/jpeg\`, or \`image/webp\` (when \`encoding: 'binary'\`, the default)
   * - Data URI string with \`Content-Type: text/plain\` (when \`encoding: 'base64'\`)
   *
   * **Error:**
   * - \`BrowserRunErrorResponse\` JSON with appropriate HTTP status code (400, 422, 429, 500, 503)
   *
   * **Headers:**
   * - \`X-Browser-Ms-Used\`: Browser time consumed in milliseconds (set when status < 500)
   */
  quickAction(
    action: 'screenshot',
    options: BrowserRunScreenshotOptions
  ): Promise<Response>;

  /**
   * Generate a PDF of a web page.
   * @param action - Must be \`'pdf'\`.
   * @param options - PDF generation options including page size, margins, and headers/footers.
   * @returns A \`Response\` containing one of:
   *
   * **Success (HTTP 200):**
   * - Binary PDF data with \`Content-Type: application/pdf\`
   *
   * **Error:**
   * - \`BrowserRunErrorResponse\` JSON with appropriate HTTP status code (400, 422, 429, 500, 503)
   *
   * **Headers:**
   * - \`X-Browser-Ms-Used\`: Browser time consumed in milliseconds (set when status < 500)
   */
  quickAction(action: 'pdf', options: BrowserRunPDFOptions): Promise<Response>;

  /**
   * Get the HTML content of a web page.
   * @param action - Must be \`'content'\`.
   * @param options - Navigation and page interaction options.
   * @returns A \`Response\` containing one of:
   *
   * **Success (HTTP 200):**
   * - \`BrowserRunContentSuccessResponse\` JSON with \`Content-Type: application/json\`
   *
   * **Error:**
   * - \`BrowserRunErrorResponse\` JSON with appropriate HTTP status code (400, 422, 429, 500, 503)
   *
   * **Headers:**
   * - \`X-Browser-Ms-Used\`: Browser time consumed in milliseconds (set when status < 500)
   */
  quickAction(
    action: 'content',
    options: BrowserRunContentOptions
  ): Promise<Response>;

  /**
   * Scrape elements from a web page by CSS selector.
   * @param action - Must be \`'scrape'\`.
   * @param options - Scrape options with CSS selectors for elements to extract.
   * @returns A \`Response\` containing one of:
   *
   * **Success (HTTP 200):**
   * - \`BrowserRunScrapeSuccessResponse\` JSON with \`Content-Type: application/json\`
   *
   * **Error:**
   * - \`BrowserRunErrorResponse\` JSON with appropriate HTTP status code (400, 422, 429, 500, 503)
   *
   * **Headers:**
   * - \`X-Browser-Ms-Used\`: Browser time consumed in milliseconds (set when status < 500)
   */
  quickAction(
    action: 'scrape',
    options: BrowserRunScrapeOptions
  ): Promise<Response>;

  /**
   * Extract all links from a web page.
   * @param action - Must be \`'links'\`.
   * @param options - Options to filter visible or internal links only.
   * @returns A \`Response\` containing one of:
   *
   * **Success (HTTP 200):**
   * - \`BrowserRunLinksSuccessResponse\` JSON with \`Content-Type: application/json\`
   *
   * **Error:**
   * - \`BrowserRunErrorResponse\` JSON with appropriate HTTP status code (400, 422, 429, 500, 503)
   *
   * **Headers:**
   * - \`X-Browser-Ms-Used\`: Browser time consumed in milliseconds (set when status < 500)
   */
  quickAction(
    action: 'links',
    options: BrowserRunLinksOptions
  ): Promise<Response>;

  /**
   * Get several representations of a web page in one request.
   * @param action - Must be \`'snapshot'\`.
   * @param options - Snapshot options including the \`formats\` to return and
   * screenshot settings (encoding is always base64).
   * @returns A \`Response\` containing one of:
   *
   * **Success (HTTP 200):**
   * - \`BrowserRunSnapshotSuccessResponse\` JSON with \`Content-Type: application/json\`
   *
   * **Error:**
   * - \`BrowserRunErrorResponse\` JSON with appropriate HTTP status code (400, 422, 429, 500, 503)
   *
   * **Headers:**
   * - \`X-Browser-Ms-Used\`: Browser time consumed in milliseconds (set when status < 500)
   */
  quickAction(
    action: 'snapshot',
    options: BrowserRunSnapshotOptions
  ): Promise<Response>;

  /**
   * Extract structured JSON data from a web page using AI.
   * @param action - Must be \`'json'\`.
   * @param options - JSON extraction options with prompt or response_format schema.
   * @returns A \`Response\` containing one of:
   *
   * **Success (HTTP 200):**
   * - \`BrowserRunJsonSuccessResponse\` JSON with \`Content-Type: application/json\`
   *
   * **Error:**
   * - \`BrowserRunErrorResponse\` JSON with appropriate HTTP status code (400, 422, 429, 500, 503)
   * - HTTP 422 with code \`2012\` for HTML-to-markdown conversion failures
   * - HTTP 422/500 for AI extraction failures (may include \`rawAiResponse\` field)
   *
   * **Headers:**
   * - \`X-Browser-Ms-Used\`: Browser time consumed in milliseconds (set when status < 500)
   */
  quickAction(
    action: 'json',
    options: BrowserRunJsonOptions
  ): Promise<Response>;

  /**
   * Convert a web page to Markdown.
   * @param action - Must be \`'markdown'\`.
   * @param options - Navigation and page interaction options.
   * @returns A \`Response\` containing one of:
   *
   * **Success (HTTP 200):**
   * - \`BrowserRunMarkdownSuccessResponse\` JSON with \`Content-Type: application/json\`
   *
   * **Error:**
   * - \`BrowserRunErrorResponse\` JSON with appropriate HTTP status code (400, 422, 429, 500, 503)
   * - HTTP 422 with code \`2012\` for HTML-to-markdown conversion failures
   *
   * **Headers:**
   * - \`X-Browser-Ms-Used\`: Browser time consumed in milliseconds (set when status < 500)
   */
  quickAction(
    action: 'markdown',
    options: BrowserRunMarkdownOptions
  ): Promise<Response>;

  /**
   * Get the accessibility tree of a web page.
   * @param action - Must be \`'accessibilityTree'\`.
   * @param options - Options to scope the tree to a subtree and to control
   * whether semantically uninteresting nodes are pruned.
   * @returns A \`Response\` containing one of:
   *
   * **Success (HTTP 200):**
   * - \`BrowserRunAccessibilityTreeSuccessResponse\` JSON with \`Content-Type: application/json\`
   * - \`result.accessibilityTree\` is \`null\` when \`root\` matched no element
   *
   * **Error:**
   * - \`BrowserRunErrorResponse\` JSON with appropriate HTTP status code (400, 422, 429, 500, 503)
   * - HTTP 422 for a malformed \`root\` selector
   * - HTTP 500 with code \`2017\` or \`2018\` when the tree could not be built
   *
   * **Headers:**
   * - \`X-Browser-Ms-Used\`: Browser time consumed in milliseconds (set when status < 500)
   */
  quickAction(
    action: 'accessibilityTree',
    options: BrowserRunAccessibilityTreeOptions
  ): Promise<Response>;
  /** Acquire a new browser session and return its metadata. */
  acquire(options?: BrowserRunAcquireOptions): Promise<BrowserRunAcquireResult>;

  /** Acquire a browser session and return a session-pinned WebSocket capability. */
  launch(options?: BrowserRunAcquireOptions): Promise<BrowserRunConnection>;

  /** Return a session-pinned WebSocket capability for an existing session. */
  connectSession(
    sessionId: string,
    options?: BrowserRunConnectOptions
  ): Promise<BrowserRunConnection>;

  /** Mint an authenticated live-view link for a browser session. */
  getLiveView(
    sessionId: string,
    options?: BrowserRunLiveViewOptions
  ): Promise<BrowserRunLiveView>;

  /** List the caller's active browser sessions. */
  listSessions(
    options?: BrowserRunListSessionsOptions
  ): Promise<BrowserRunSession[]>;

  /** List recent active and closed browser sessions. */
  history(options?: BrowserRunHistoryOptions): Promise<BrowserRunSession[]>;

  /** Return the caller's browser-session and browser-time limits. */
  limits(): Promise<BrowserRunLimits>;

  /** Return details for one browser session, or \`null\` when it does not exist. */
  getSession(sessionId: string): Promise<BrowserRunSession | null>;

  /** Close a browser session. */
  closeSession(sessionId: string): Promise<BrowserRunCloseSessionResult>;

  /** DevTools JSON methods exposed through one nested binding target. */
  get devtools(): BrowserRunDevtools;
}

/**
 * In addition to the properties you can set in the RequestInit dict
 * that you pass as an argument to the Request constructor, you can
 * set certain properties of a \`cf\` object to control how Cloudflare
 * features are applied to that new Request.
 *
 * Note: Currently, these properties cannot be tested in the
 * playground.
 */
interface RequestInitCfProperties extends Record<string, unknown> {
  cacheEverything?: boolean;
  /**
   * A request's cache key is what determines if two requests are
   * "the same" for caching purposes. If a request has the same cache key
   * as some previous request, then we can serve the same cached response for
   * both. (e.g. 'some-key')
   *
   * Only available for Enterprise customers.
   */
  cacheKey?: string;
  /**
   * This allows you to append additional Cache-Tag response headers
   * to the origin response without modifications to the origin server.
   * This will allow for greater control over the Purge by Cache Tag feature
   * utilizing changes only in the Workers process.
   *
   * Only available for Enterprise customers.
   */
  cacheTags?: string[];
  /**
   * Force response to be cached for a given number of seconds. (e.g. 300)
   */
  cacheTtl?: number;
  /**
   * Force response to be cached for a given number of seconds based on the Origin status code.
   * (e.g. { '200-299': 86400, '404': 1, '500-599': 0 })
   */
  cacheTtlByStatus?: Record<string, number>;
  /**
   * Controls whether Cloudflare uses range requests when fetching the response
   * from the origin.
   *
   * - \`"on"\`: enable origin range requests for this request.
   * - \`"off"\`: disable origin range requests for this request.
   */
  originRangeRequests?: "on" | "off";
  /** Controls how responses with a \`Vary\` header are cached for this request. */
  vary?: RequestInitCfPropertiesVary;
  /**
   * Explicit Cache-Control header value to set on the response stored in cache.
   * This gives full control over cache directives (e.g. 'public, max-age=3600, s-maxage=86400').
   *
   * Cannot be used together with \`cacheTtl\` or the \`cache\` request option (\`no-store\`/\`no-cache\`),
   * as these are mutually exclusive cache control mechanisms. Setting both will throw a TypeError.
   *
   * Can be used together with \`cacheTtlByStatus\`.
   */
  cacheControl?: string;
  /**
   * Whether the response should be eligible for Cache Reserve storage.
   */
  cacheReserveEligible?: boolean;
  /**
   * Whether to respect strong ETags (as opposed to weak ETags) from the origin.
   */
  respectStrongEtag?: boolean;
  /**
   * Whether to strip ETag headers from the origin response before caching.
   */
  stripEtags?: boolean;
  /**
   * Whether to strip Last-Modified headers from the origin response before caching.
   */
  stripLastModified?: boolean;
  /**
   * Whether to enable Cache Deception Armor, which protects against web cache
   * deception attacks by verifying the Content-Type matches the URL extension.
   */
  cacheDeceptionArmor?: boolean;
  /**
   * Minimum file size in bytes for a response to be eligible for Cache Reserve storage.
   */
  cacheReserveMinimumFileSize?: number;
  scrapeShield?: boolean;
  apps?: boolean;
  /**
   * Controls whether an outbound gRPC-web subrequest from this Worker is
   * converted to gRPC at the Cloudflare edge.
   *
   * - \`"passthrough"\`: forward the subrequest unchanged as gRPC-web (default).
   * - \`"convert"\`: convert the gRPC-web subrequest to gRPC at the edge.
   *
   * Provides per-request control over the same edge conversion behavior
   * gated by the \`auto_grpc_convert\` compatibility flag.
   */
  grpcWeb?: "passthrough" | "convert";
  image?: RequestInitCfPropertiesImage;
  minify?: RequestInitCfPropertiesImageMinify;
  mirage?: boolean;
  polish?: "lossy" | "lossless" | "off";
  r2?: RequestInitCfPropertiesR2;
  /**
   * Redirects the request to an alternate origin server. You can use this,
   * for example, to implement load balancing across several origins.
   * (e.g.us-east.example.com)
   *
   * Note - For security reasons, the hostname set in resolveOverride must
   * be proxied on the same Cloudflare zone of the incoming request.
   * Otherwise, the setting is ignored. CNAME hosts are allowed, so to
   * resolve to a host under a different domain or a DNS only domain first
   * declare a CNAME record within your own zone\u2019s DNS mapping to the
   * external hostname, set proxy on Cloudflare, then set resolveOverride
   * to point to that CNAME record.
   */
  resolveOverride?: string;
}

/**
 * Controls how Workers Standard Vary handles a request header listed by an
 * origin \`Vary\` response header:
 *
 * - \`"normalize"\`: normalize the request header value before it is used in the
 *   cache variance key.
 * - \`"passthrough"\`: use the raw request header value in the cache variance
 *   key.
 * - \`"bypass"\`: bypass cache when the header appears in the origin \`Vary\`
 *   response header.
 */
type RequestInitCfPropertiesVaryAction =
  | "normalize"
  | "passthrough"
  | "bypass";

/** Configuration for Workers Standard Vary support. */
interface RequestInitCfPropertiesVary {
  /** The fallback action for varied request headers not listed in \`headers\`. */
  default: RequestInitCfPropertiesVaryHeader;
  /**
   * Lowercase request header names and their Vary configuration.
   *
   * The \`accept\` header can include \`media_types\`, the \`accept-language\`
   * header can include \`languages\`, and other headers support only \`action\`.
   */
  headers?: RequestInitCfPropertiesVaryHeaders;
}

/** Common Vary behavior for a single request header. */
interface RequestInitCfPropertiesVaryHeader {
  /** How this request header contributes to cache variance. */
  action: RequestInitCfPropertiesVaryAction;
}

/** Vary behavior for the \`accept\` request header. */
interface RequestInitCfPropertiesVaryAcceptHeader
  extends RequestInitCfPropertiesVaryHeader {
  /**
   * Media types to keep when normalizing the \`Accept\` request header.
   *
   * Named \`media_types\` to match the serialized \`cf.vary\` configuration.
   */
  media_types?: string[];
}

