  "accept-language"?: RequestInitCfPropertiesVaryAcceptLanguageHeader;
  [header: string]:
    | RequestInitCfPropertiesVaryHeader
    | RequestInitCfPropertiesVaryAcceptHeader
    | RequestInitCfPropertiesVaryAcceptLanguageHeader
    | undefined;
